  static let bluetoothDiscoveryForeground = "signalasi.hardware.bluetooth.discovery.foreground"
  static let bluetoothPairingHandoff = "signalasi.hardware.bluetooth.pairing.handoff"
  static let nfcStatus = "signalasi.hardware.nfc.status"
  static let batteryStatus = "signalasi.hardware.battery.status"
  static let powerStatus = "signalasi.hardware.power.status"
