final class AgentExplicitToolHandleRegistry {
  static let defaultTTLMillis: Int64 = 30 * 60 * 1_000
  static let defaultIdleTimeoutMillis: Int64 = 10 * 60 * 1_000
  static let maxTTLMillis: Int64 = 24 * 60 * 60 * 1_000

  private struct Entry {
    var handleId: String
    var kind: String
    var resourceId: String
    var ownerId: String
    var contextId: String
    var capabilities: Set<String>
    var resource: AgentExplicitToolHandleResource
    var metadata: AgentRunControlPayload
    var createdAtEpochMillis: Int64
    var lastUsedAtEpochMillis: Int64
    var expiresAtEpochMillis: Int64
    var idleTimeoutMillis: Int64
    var useCount: Int64
  }

  private let lock = NSRecursiveLock()
  private let nowMillis: () -> Int64
  private let maximumHandles: Int
  private var entries: [String: Entry] = [:]

  init(
    nowMillis: @escaping () -> Int64 = { Int64(Date().timeIntervalSince1970 * 1_000) },
    maxHandles: Int = 512
  ) {
    self.nowMillis = nowMillis
    self.maximumHandles = Swift.max(maxHandles, 1)
  }

  func create(
    kind: String,
    resourceId: String,
    scope: AgentExplicitToolHandleScope,
    capabilities: Set<String>,
    resource: AgentExplicitToolHandleResource? = nil,
    ttlMillis: Int64 = AgentExplicitToolHandleRegistry.defaultTTLMillis,
    idleTimeoutMillis: Int64 = AgentExplicitToolHandleRegistry.defaultIdleTimeoutMillis,
    metadata: AgentRunControlPayload = [:]
  ) throws -> AgentExplicitToolHandlePublicRecord {
    let normalizedKind = try checked(kind, field: "kind", maxLength: 80).lowercased()
    guard isValidKind(normalizedKind) else {
      throw AgentExplicitToolHandleError(code: "tool_handle_kind_invalid", message: "Tool handle kind is invalid")
    }
    let normalizedResourceId = try checked(resourceId, field: "resource_id", maxLength: 512)
    guard !normalizedResourceId.isEmpty else {
      throw AgentExplicitToolHandleError(
        code: "tool_handle_resource_required",
        message: "Tool handle resource is required"
      )
    }
    let normalizedScope = try normalize(scope)
    let normalizedCapabilities = try normalizeCapabilities(capabilities)
    let publicMetadata = try normalizeMetadata(metadata)
    let now = nowMillis()
    let ttl = Swift.min(Swift.max(ttlMillis, 1), Self.maxTTLMillis)
    let idle = Swift.min(Swift.max(idleTimeoutMillis, 0), ttl)
    return try synchronized {
      pruneLocked(now: now)
      while entries.count >= maximumHandles {
        guard let oldest = entries.values.sorted(by: {
          if $0.lastUsedAtEpochMillis == $1.lastUsedAtEpochMillis {
            return $0.createdAtEpochMillis < $1.createdAtEpochMillis
          }
          return $0.lastUsedAtEpochMillis < $1.lastUsedAtEpochMillis
        }).first else {
          break
        }
        entries.removeValue(forKey: oldest.handleId)
      }
      let handleId = newHandleId(kind: normalizedKind)
      let entry = Entry(
        handleId: handleId,
        kind: normalizedKind,
        resourceId: normalizedResourceId,
        ownerId: normalizedScope.ownerId,
        contextId: normalizedScope.contextId,
        capabilities: normalizedCapabilities,
        resource: resource ?? AgentExplicitToolHandleResource(resourceId: normalizedResourceId),
        metadata: publicMetadata,
        createdAtEpochMillis: now,
        lastUsedAtEpochMillis: now,
        expiresAtEpochMillis: now + ttl,
        idleTimeoutMillis: idle,
        useCount: 0
      )
      entries[handleId] = entry
      return publicRecord(entry)
    }
  }

  func resolve(
    handleId: String,
    kind: String,
    scope: AgentExplicitToolHandleScope,
    requiredCapability: String
  ) throws -> AgentExplicitToolHandleResolution {
    let normalizedHandleId = try checked(handleId, field: "handle_id", maxLength: 240)
    let normalizedKind = try checked(kind, field: "kind", maxLength: 80).lowercased()
    let normalizedScope = try normalize(scope)
    let capability = try checked(requiredCapability, field: "required_capability", maxLength: 160)
    let now = nowMillis()
    return try synchronized {
      guard var entry = entries[normalizedHandleId] else {
        throw AgentExplicitToolHandleError(
          code: "tool_handle_not_found",
          message: "Tool handle is missing, expired, or was released",
          retryable: true
        )
      }
      if expired(entry, now: now) {
        entries.removeValue(forKey: normalizedHandleId)
        throw AgentExplicitToolHandleError(
          code: "tool_handle_expired",
          message: "Tool handle expired; create a new handle and retry",
          retryable: true
        )
      }
      guard entry.kind == normalizedKind else {
        throw AgentExplicitToolHandleError(
          code: "tool_handle_kind_mismatch",
          message: "Tool handle belongs to a different resource type"
        )
      }
      guard entry.ownerId == normalizedScope.ownerId else {
        throw AgentExplicitToolHandleError(
          code: "tool_handle_owner_mismatch",
          message: "Tool handle belongs to a different caller"
        )
      }
      if !entry.contextId.isEmpty && entry.contextId != normalizedScope.contextId {
        throw AgentExplicitToolHandleError(
          code: "tool_handle_context_mismatch",
          message: "Tool handle belongs to a different conversation context"
        )
      }
      guard entry.capabilities.contains(capability) else {
        throw AgentExplicitToolHandleError(
          code: "tool_handle_capability_denied",
          message: "Tool handle does not grant the requested capability"
        )
      }
      entry.lastUsedAtEpochMillis = now
      entry.useCount += 1
      entries[normalizedHandleId] = entry
      return AgentExplicitToolHandleResolution(
        handleId: entry.handleId,
        kind: entry.kind,
        capabilities: entry.capabilities,
        resourceId: entry.resourceId,
        resource: entry.resource,
        expiresAtEpochMillis: entry.expiresAtEpochMillis,
        useCount: entry.useCount
      )
    }
  }

  func release(
    handleId: String,
    scope: AgentExplicitToolHandleScope
  ) throws -> Bool {
    let normalizedHandleId = try checked(handleId, field: "handle_id", maxLength: 240)
    let normalizedScope = try normalize(scope)
    return try synchronized {
      guard let entry = entries[normalizedHandleId] else {
        return false
      }
      guard entry.ownerId == normalizedScope.ownerId else {
        throw AgentExplicitToolHandleError(
          code: "tool_handle_owner_mismatch",
          message: "Tool handle belongs to a different caller"
        )
      }
      if !entry.contextId.isEmpty && entry.contextId != normalizedScope.contextId {
        throw AgentExplicitToolHandleError(
          code: "tool_handle_context_mismatch",
          message: "Tool handle belongs to a different conversation context"
        )
      }
      entries.removeValue(forKey: normalizedHandleId)
      return true
    }
  }

  func revokeResource(
    kind: String,
    resourceId: String
  ) throws -> Int {
    let normalizedKind = try checked(kind, field: "kind", maxLength: 80).lowercased()
    let normalizedResourceId = try checked(resourceId, field: "resource_id", maxLength: 512)
    return synchronized {
      let targets = entries.values
        .filter { $0.kind == normalizedKind && $0.resourceId == normalizedResourceId }
        .map(\.handleId)
      targets.forEach { entries.removeValue(forKey: $0) }
      return targets.count
    }
  }

  func status() -> AgentExplicitToolHandleStatus {
    synchronized {
      pruneLocked(now: nowMillis())
      var byKind: [String: Int] = [:]
      entries.values.forEach { byKind[$0.kind, default: 0] += 1 }
      return AgentExplicitToolHandleStatus(
        contract: AgentExplicitToolHandleContract.version,
        activeCount: entries.count,
        byKind: byKind
      )
    }
  }

  private func synchronized<T>(_ body: () throws -> T) rethrows -> T {
    lock.lock()
    defer { lock.unlock() }
    return try body()
  }

  private func pruneLocked(now: Int64) {
    let expiredIds = entries.values.filter { expired($0, now: now) }.map(\.handleId)
    expiredIds.forEach { entries.removeValue(forKey: $0) }
  }

  private func expired(_ entry: Entry, now: Int64) -> Bool {
    now >= entry.expiresAtEpochMillis ||
      entry.idleTimeoutMillis > 0 && now >= entry.lastUsedAtEpochMillis + entry.idleTimeoutMillis
  }

  private func publicRecord(_ entry: Entry) -> AgentExplicitToolHandlePublicRecord {
    AgentExplicitToolHandlePublicRecord(
      contract: AgentExplicitToolHandleContract.version,
      handleId: entry.handleId,
      kind: entry.kind,
      capabilities: entry.capabilities.sorted(),
      ownerId: entry.ownerId,
      contextId: entry.contextId,
      metadata: entry.metadata,
      createdAtEpochMillis: entry.createdAtEpochMillis,
      lastUsedAtEpochMillis: entry.lastUsedAtEpochMillis,
      expiresAtEpochMillis: entry.expiresAtEpochMillis,
      useCount: entry.useCount
    )
  }

  private func normalize(_ scope: AgentExplicitToolHandleScope) throws -> AgentExplicitToolHandleScope {
    let ownerId = try checked(scope.ownerId, field: "owner_id", maxLength: 240)
    guard !ownerId.isEmpty else {
      throw AgentExplicitToolHandleError(
        code: "tool_handle_owner_required",
        message: "Tool handle owner is required"
      )
    }
    return AgentExplicitToolHandleScope(
      ownerId: ownerId,
      contextId: try checked(scope.contextId, field: "context_id", maxLength: 240)
    )
  }

  private func normalizeCapabilities(_ capabilities: Set<String>) throws -> Set<String> {
    let normalized = Set(try capabilities.map {
      try checked($0, field: "capability", maxLength: 160)
    }.filter { !$0.isEmpty })
    guard !normalized.isEmpty else {
      throw AgentExplicitToolHandleError(
        code: "tool_handle_capability_required",
        message: "Tool handle requires at least one capability"
      )
    }
    return normalized
  }

  private func normalizeMetadata(_ metadata: AgentRunControlPayload) throws -> AgentRunControlPayload {
    guard metadata.count <= Self.maxMetadataItems else {
      throw AgentExplicitToolHandleError(
        code: "tool_handle_input_invalid",
        message: "Tool handle metadata has too many entries"
      )
    }
    var normalized: AgentRunControlPayload = [:]
    for key in metadata.keys.sorted() {
      let normalizedKey = try checked(key, field: "metadata key", maxLength: 80)
      guard !normalizedKey.isEmpty else {
        continue
      }
      if case .string(let value)? = metadata[key] {
        normalized[normalizedKey] = .string(try checked(value, field: "metadata \(normalizedKey)", maxLength: 240))
      } else if let value = metadata[key] {
        normalized[normalizedKey] = value
      }
    }
    return normalized
  }

  private func checked(
    _ value: String,
    field: String,
    maxLength: Int
  ) throws -> String {
    let normalized = value.trimmingCharacters(in: .whitespacesAndNewlines)
    if normalized.count > maxLength || normalized.unicodeScalars.contains(where: { $0.value < 32 }) {
      throw AgentExplicitToolHandleError(
        code: "tool_handle_input_invalid",
        message: "\(field) exceeds its safe limit"
      )
    }
    return normalized
  }

  private func isValidKind(_ kind: String) -> Bool {
    kind.range(of: Self.kindPattern, options: .regularExpression) != nil
  }

  private func newHandleId(kind: String) -> String {
    let prefix = kind.filter { $0.isLetter || $0.isNumber }.prefix(8)
    let random = UUID().uuidString.replacingOccurrences(of: "-", with: "").lowercased()
    return "sth_\(prefix)_\(random)"
  }

  private static let kindPattern = #"^[a-z0-9][a-z0-9._-]{0,79}$"#
  private static let maxMetadataItems = 32
}

enum AgentPrivateDataExportPolicy: String, Codable, CaseIterable, Identifiable {
  case alwaysEncrypted = "ALWAYS_ENCRYPTED"
  case optionalContacts = "OPTIONAL_CONTACTS"
  case optionalSessionHistory = "OPTIONAL_SESSION_HISTORY"
  case neverExport = "NEVER_EXPORT"

  var id: String { rawValue }

  static func fromWireValue(_ value: String?) -> AgentPrivateDataExportPolicy {
    let normalized = value?.trimmingCharacters(in: .whitespacesAndNewlines).uppercased() ?? ""
    return allCases.first { $0.rawValue == normalized } ?? .neverExport
  }

  init(from decoder: Decoder) throws {
    let container = try decoder.singleValueContainer()
    self = Self.fromWireValue(try container.decode(String.self))
  }

  func encode(to encoder: Encoder) throws {
    var container = encoder.singleValueContainer()
    try container.encode(rawValue)
  }
}

enum AgentPrivateDataSensitivity: String, Codable, CaseIterable, Identifiable {
  case personal = "PERSONAL"
  case secret = "SECRET"
  case ephemeral = "EPHEMERAL"

  var id: String { rawValue }

  static func fromWireValue(_ value: String?) -> AgentPrivateDataSensitivity {
    let normalized = value?.trimmingCharacters(in: .whitespacesAndNewlines).uppercased() ?? ""
    return allCases.first { $0.rawValue == normalized } ?? .personal
  }

  init(from decoder: Decoder) throws {
    let container = try decoder.singleValueContainer()
    self = Self.fromWireValue(try container.decode(String.self))
  }

  func encode(to encoder: Encoder) throws {
    var container = encoder.singleValueContainer()
    try container.encode(rawValue)
  }
}

enum AgentPrivateDataErasePolicy: String, Codable, CaseIterable, Identifiable {
  case delete = "DELETE"
  case deleteAndRotateIdentity = "DELETE_AND_ROTATE_IDENTITY"

  var id: String { rawValue }

  static func fromWireValue(_ value: String?) -> AgentPrivateDataErasePolicy {
    let normalized = value?.trimmingCharacters(in: .whitespacesAndNewlines).uppercased() ?? ""
    return allCases.first { $0.rawValue == normalized } ?? .delete
  }

  init(from decoder: Decoder) throws {
    let container = try decoder.singleValueContainer()
    self = Self.fromWireValue(try container.decode(String.self))
  }

  func encode(to encoder: Encoder) throws {
    var container = encoder.singleValueContainer()
    try container.encode(rawValue)
  }
}

struct AgentPrivateDataDescriptor: Codable, Equatable, Identifiable {
  var id: String
  var category: String
  var storageIds: Set<String>
  var backupPath: String
  var exportPolicy: AgentPrivateDataExportPolicy
  var sensitivity: AgentPrivateDataSensitivity
  var erasePolicy: AgentPrivateDataErasePolicy

  init(
    id: String,
    category: String,
    storageIds: Set<String>,
    backupPath: String = "",
    exportPolicy: AgentPrivateDataExportPolicy,
    sensitivity: AgentPrivateDataSensitivity,
    erasePolicy: AgentPrivateDataErasePolicy = .delete
  ) {
    self.id = id
    self.category = category
    self.storageIds = storageIds
    self.backupPath = backupPath
    self.exportPolicy = exportPolicy
    self.sensitivity = sensitivity
    self.erasePolicy = erasePolicy
  }

  enum CodingKeys: String, CodingKey {
    case id
    case category
    case storageIds = "storage_ids"
    case backupPath = "backup_path"
    case exportPolicy = "export_policy"
    case sensitivity
    case erasePolicy = "erase_policy"
  }
}

struct AgentPrivateDataInventoryAudit: Codable, Equatable {
  var duplicateIds: Set<String>
  var descriptorsWithoutStorage: Set<String>
  var exportedDescriptorsWithoutPath: Set<String>
  var nonExportedDescriptorsWithPath: Set<String>
  var identityRotationCount: Int

  var complete: Bool {
    duplicateIds.isEmpty &&
      descriptorsWithoutStorage.isEmpty &&
      exportedDescriptorsWithoutPath.isEmpty &&
      nonExportedDescriptorsWithPath.isEmpty &&
      identityRotationCount == 1
  }

  enum CodingKeys: String, CodingKey {
    case duplicateIds = "duplicate_ids"
    case descriptorsWithoutStorage = "descriptors_without_storage"
    case exportedDescriptorsWithoutPath = "exported_descriptors_without_path"
    case nonExportedDescriptorsWithPath = "non_exported_descriptors_with_path"
    case identityRotationCount = "identity_rotation_count"
  }
}

struct AgentPrivateDataBackupManifest: Codable, Equatable {
  var policyVersion: Int
  var encryptedContainerRequired: Bool
  var privateModeExported: Bool
  var pausedTrackingExported: Bool
  var identityRotatedOnReset: Bool
  var includedStoreIds: [String]
  var secretStoreIds: [String]
  var excludedStoreIds: [String]
  var eraseStoreIds: [String]

  enum CodingKeys: String, CodingKey {
    case policyVersion = "policy_version"
    case encryptedContainerRequired = "encrypted_container_required"
    case privateModeExported = "private_mode_exported"
    case pausedTrackingExported = "paused_tracking_exported"
    case identityRotatedOnReset = "identity_rotated_on_reset"
    case includedStoreIds = "included_store_ids"
    case secretStoreIds = "secret_store_ids"
    case excludedStoreIds = "excluded_store_ids"
    case eraseStoreIds = "erase_store_ids"
  }
}

