  static func backupManifest(
    includeContacts: Bool,
    includeSessionHistory: Bool
  ) -> AgentPrivateDataBackupManifest {
    let included = descriptors.filter {
      shouldExport(
        descriptor: $0,
        includeContacts: includeContacts,
        includeSessionHistory: includeSessionHistory
      )
    }
    let includedIds = Set(included.map(\.id))
    let excluded = descriptors.filter { !includedIds.contains($0.id) }
    return AgentPrivateDataBackupManifest(
      policyVersion: policyVersion,
      encryptedContainerRequired: true,
      privateModeExported: false,
      pausedTrackingExported: false,
      identityRotatedOnReset: true,
      includedStoreIds: included.map(\.id),
      secretStoreIds: included.filter { $0.sensitivity == .secret }.map(\.id),
      excludedStoreIds: excluded.map(\.id),
      eraseStoreIds: descriptors.map(\.id)
    )
  }

  static func shouldExport(
    descriptor: AgentPrivateDataDescriptor,
    includeContacts: Bool,
    includeSessionHistory: Bool
  ) -> Bool {
    switch descriptor.exportPolicy {
    case .alwaysEncrypted:
      return true
    case .optionalContacts:
      return includeContacts
    case .optionalSessionHistory:
      return includeSessionHistory
    case .neverExport:
      return false
    }
  }

  static func audit() -> AgentPrivateDataInventoryAudit {
    var idCounts: [String: Int] = [:]
    descriptors.forEach { idCounts[$0.id, default: 0] += 1 }
    return AgentPrivateDataInventoryAudit(
      duplicateIds: Set(idCounts.filter { $0.value > 1 }.map(\.key)),
      descriptorsWithoutStorage: Set(descriptors.filter { $0.storageIds.isEmpty }.map(\.id)),
      exportedDescriptorsWithoutPath: Set(descriptors.filter {
        $0.exportPolicy != .neverExport && $0.backupPath.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
      }.map(\.id)),
      nonExportedDescriptorsWithPath: Set(descriptors.filter {
        $0.exportPolicy == .neverExport && !$0.backupPath.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
      }.map(\.id)),
      identityRotationCount: descriptors.filter { $0.erasePolicy == .deleteAndRotateIdentity }.count
    )
  }

  private static func item(
    _ id: String,
    _ category: String,
    _ storageIds: String...,
    backupPath: String,
    exportPolicy: AgentPrivateDataExportPolicy = .alwaysEncrypted,
    sensitivity: AgentPrivateDataSensitivity = .personal,
    erasePolicy: AgentPrivateDataErasePolicy = .delete
  ) -> AgentPrivateDataDescriptor {
    AgentPrivateDataDescriptor(
      id: id,
      category: category,
      storageIds: Set(storageIds),
      backupPath: backupPath,
      exportPolicy: exportPolicy,
      sensitivity: sensitivity,
      erasePolicy: erasePolicy
    )
  }

  private static func localOnly(
    _ id: String,
    _ category: String,
    _ storageId: String,
    _ sensitivity: AgentPrivateDataSensitivity
  ) -> AgentPrivateDataDescriptor {
    AgentPrivateDataDescriptor(
      id: id,
      category: category,
      storageIds: [storageId],
      exportPolicy: .neverExport,
      sensitivity: sensitivity
    )
  }
}

enum AgentMcpJSONValue: Codable, Equatable {
  case string(String)
  case int(Int64)
  case double(Double)
  case bool(Bool)
  case object([String: AgentMcpJSONValue])
  case array([AgentMcpJSONValue])
  case null

  var boolValue: Bool? {
    if case .bool(let value) = self {
      return value
    }
    return nil
  }

  var stringValue: String? {
    switch self {
    case .string(let value):
      return value
    case .int(let value):
      return String(value)
    case .double(let value):
      return String(value)
    case .bool(let value):
      return value ? "true" : "false"
    case .object, .array, .null:
      return nil
    }
  }

  var intValue: Int64? {
    switch self {
    case .int(let value):
      return value
    case .double(let value):
      return Int64(value)
    case .string(let value):
      return Int64(value)
    case .bool, .object, .array, .null:
      return nil
    }
  }

  var objectValue: AgentMcpJSONObject? {
    if case .object(let value) = self {
      return value
    }
    return nil
  }

  init(from decoder: Decoder) throws {
    let container = try decoder.singleValueContainer()
    if container.decodeNil() {
      self = .null
    } else if let value = try? container.decode(Bool.self) {
      self = .bool(value)
    } else if let value = try? container.decode(Int64.self) {
      self = .int(value)
    } else if let value = try? container.decode(Double.self) {
      self = .double(value)
    } else if let value = try? container.decode(String.self) {
      self = .string(value)
    } else if let value = try? container.decode([String: AgentMcpJSONValue].self) {
      self = .object(value)
    } else {
      self = .array((try? container.decode([AgentMcpJSONValue].self)) ?? [])
    }
  }

  func encode(to encoder: Encoder) throws {
    var container = encoder.singleValueContainer()
    switch self {
    case .string(let value):
      try container.encode(value)
    case .int(let value):
      try container.encode(value)
    case .double(let value):
      try container.encode(value)
    case .bool(let value):
      try container.encode(value)
    case .object(let value):
      try container.encode(value)
    case .array(let value):
      try container.encode(value)
    case .null:
      try container.encodeNil()
    }
  }
}

typealias AgentMcpJSONObject = [String: AgentMcpJSONValue]

private extension AgentMcpJSONValue {
  var strictStringValue: String? {
    if case .string(let value) = self {
      return value
    }
    return nil
  }

  var arrayValue: [AgentMcpJSONValue]? {
    if case .array(let value) = self {
      return value
    }
    return nil
  }

  var integerForSchema: Int? {
    switch self {
    case .int(let value):
      return Int(value)
    case .double(let value) where value.isFinite && value.rounded(.towardZero) == value:
      return Int(value)
    default:
      return nil
    }
  }

  var doubleForSchema: Double? {
    switch self {
    case .int(let value):
      return Double(value)
    case .double(let value) where value.isFinite:
      return value
    default:
      return nil
    }
  }
}

private extension String {
  var nilIfEmpty: String? {
    isEmpty ? nil : self
  }
}

enum AgentMcpJSONCodec {
  static func stringify(_ value: AgentMcpJSONValue) -> String {
    switch value {
    case .null:
      return "null"
    case .bool(let value):
      return value ? "true" : "false"
    case .int(let value):
      return String(value)
    case .double(let value):
      guard value.isFinite else {
        return "null"
      }
      return String(value)
    case .string(let value):
      return quote(value)
    case .array(let values):
      return "[" + values.map(stringify).joined(separator: ",") + "]"
    case .object(let object):
      return "{" + object.keys.sorted().map { key in
        "\(quote(key)):\(stringify(object[key] ?? .null))"
      }.joined(separator: ",") + "}"
    }
  }

  static func stringify(_ object: AgentMcpJSONObject) -> String {
    stringify(.object(object))
  }

  static func sha256(_ object: AgentMcpJSONObject) -> String {
    let digest = SHA256.hash(data: Data(stringify(object).utf8))
    return digest.map { String(format: "%02x", $0) }.joined()
  }

  private static func quote(_ value: String) -> String {
    var result = "\""
    for scalar in value.unicodeScalars {
      switch scalar.value {
      case 34:
        result += "\\\""
      case 92:
        result += "\\\\"
      case 8:
        result += "\\b"
      case 12:
        result += "\\f"
      case 10:
        result += "\\n"
      case 13:
        result += "\\r"
      case 9:
        result += "\\t"
      default:
        if scalar.value < 0x20 {
          result += String(format: "\\u%04x", scalar.value)
        } else {
          result.unicodeScalars.append(scalar)
        }
      }
    }
    result += "\""
    return result
  }
}

enum UnifiedCommandProtocolError: Error, Equatable {
  case missingCommand
}

struct UnifiedCommandResult: Codable, Equatable {
  var commandId: String
  var status: String
  var runId: String
